"""#620: list exclude-object names, and exclude one only after confirm."""
from print_handy.core.exclude_object import exclude_plan, object_names, objects_line

GCODE = """
; generated by OrcaSlicer
EXCLUDE_OBJECT_DEFINE NAME=hinge_left
EXCLUDE_OBJECT_DEFINE NAME=hinge_right
G1 X10 Y10 E0.02
"""


def test_two_named_objects_are_listed_and_a_plain_file_is_not():
    assert object_names(GCODE) == ["hinge_left", "hinge_right"]
    assert objects_line(object_names(GCODE)) == "Objects still printing: hinge_left, hinge_right"
    assert object_names("; no exclude metadata\nG1 X0 Y0\n") == []
    assert objects_line([]) == ""


def test_exclude_sends_the_name_only_after_confirm():
    names = ["hinge_left", "hinge_right"]
    asked = exclude_plan(names, "hinge_left", confirmed=False)
    assert asked["action"] == "confirm" and asked["body"] is None
    sent = exclude_plan(names, "hinge_left", confirmed=True)
    assert sent["action"] == "exclude"
    assert sent["body"]["params"]["script"] == "EXCLUDE_OBJECT NAME=hinge_left"
    assert "hinge_right" not in sent["body"]["params"]["script"]


def test_last_object_is_a_cancel_and_an_unknown_name_is_refused():
    last = exclude_plan(["only"], "only", confirmed=True)
    assert last["action"] == "cancel_print" and last["body"] is None
    missing = exclude_plan(["hinge_left"], "nope", confirmed=True)
    assert missing["action"] == "refuse" and missing["body"] is None
